#!/usr/bin/env node
/**
 * Launch script for the Temporal Workflow Dashboard.
 *
 * 1. Builds the React UI (if not already built)
 * 2. Starts the Temporal server (if not already running)
 * 3. Starts the FastAPI server (uvicorn) on a free port
 * 4. Opens the browser
 *
 * Usage: node start.js   |   npm start
 */

import { execSync, spawn } from "child_process";
import { existsSync, readFileSync } from "fs";
import { createServer } from "net";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const TEMPORAL_PKG = join(ROOT, "node_modules", "temporal-server");
const UI_DIR = join(ROOT, "ui");
const UI_DIST = join(UI_DIR, "dist", "index.html");
const CFG = JSON.parse(readFileSync(join(TEMPORAL_PKG, "configs", "server.json"), "utf8"));

function log(msg) {
  console.log(`[start] ${msg}`);
}

// --- 1. Build UI if needed ---

if (!existsSync(UI_DIST)) {
  log("Building React UI...");
  execSync("npm run build", { cwd: UI_DIR, stdio: "inherit", shell: true });
} else {
  log("UI already built");
}

// --- 2. Start Temporal if needed ---

function portUp(port) {
  return new Promise((resolve) => {
    const s = createServer();
    s.once("error", () => resolve(true)); // port in use = server running
    s.once("listening", () => { s.close(); resolve(false); });
    s.listen(port, "127.0.0.1");
  });
}

const temporalRunning = await portUp(CFG.port);
if (temporalRunning) {
  log(`Temporal already running on ${CFG.port}`);
} else {
  log("Starting Temporal server...");
  execSync(`node ${join(TEMPORAL_PKG, "scripts", "cli.js")} start`, {
    cwd: ROOT,
    stdio: "inherit",
  });
}

// --- 3. Find a free port ---

function freePort() {
  return new Promise((resolve, reject) => {
    const s = createServer();
    s.listen(0, "127.0.0.1", () => {
      const port = s.address().port;
      s.close(() => resolve(port));
    });
    s.on("error", reject);
  });
}

const port = await freePort();

// --- 4. Start uvicorn ---

log(`Starting API server on http://127.0.0.1:${port}`);

const server = spawn(
  "python",
  ["-m", "uvicorn", "server:app", "--host", "127.0.0.1", "--port", String(port)],
  { cwd: ROOT, stdio: "inherit" }
);

// --- 5. Wait for server, then open browser ---

async function waitForServer(port, timeout = 15000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await portUp(port)) return true;
    await new Promise((r) => setTimeout(r, 300));
  }
  return false;
}

if (await waitForServer(port)) {
  const url = `http://127.0.0.1:${port}`;
  log(`Dashboard ready: ${url}`);
  log(`Temporal UI:     http://${CFG.ip}:${CFG.uiPort}`);

  // open browser (cross-platform)
  const cmd = process.platform === "win32" ? "start" : process.platform === "darwin" ? "open" : "xdg-open";
  execSync(`${cmd} ${url}`, { shell: true, stdio: "ignore" });
} else {
  log("WARNING: Server did not start within 15s");
}

// forward signals to child
process.on("SIGINT", () => server.kill("SIGINT"));
process.on("SIGTERM", () => server.kill("SIGTERM"));
server.on("close", (code) => process.exit(code || 0));

"""
FastAPI backend for the Temporal workflow UI.
Runs a Temporal worker and exposes endpoints to trigger workflow scenarios.
Serves the React build from ui/dist/ if present.

Started by start.js -- not intended to be run directly.
"""

import asyncio
import json
import random
import uuid
from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles
from temporalio.client import Client
from temporalio.worker import Worker

from test import (
    IP, GRPC_PORT, HTTP_PORT, UI_PORT, TASK_QUEUE,
    ALL_WORKFLOWS, ALL_ACTIVITIES,
    Order, NewUser, PipelineConfig, ExpenseReport, BatchJob,
    OrderFulfillmentWorkflow, UserOnboardingWorkflow,
    DataPipelineWorkflow, ExpenseApprovalWorkflow,
    BatchProcessingWorkflow,
)

client: Client = None
worker_task: asyncio.Task = None


@asynccontextmanager
async def lifespan(app: FastAPI):
    global client, worker_task
    client = await Client.connect(f"{IP}:{GRPC_PORT}")
    w = Worker(
        client,
        task_queue=TASK_QUEUE,
        workflows=ALL_WORKFLOWS,
        activities=ALL_ACTIVITIES,
    )
    worker_task = asyncio.create_task(w.run())
    print(f"Worker started on queue '{TASK_QUEUE}'")
    yield
    worker_task.cancel()
    try:
        await worker_task
    except asyncio.CancelledError:
        pass


app = FastAPI(title="Temporal Workflow UI", lifespan=lifespan)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)


def wf_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:8]}"


@app.get("/api/info")
async def info():
    return {
        "grpc": f"{IP}:{GRPC_PORT}",
        "http_api": f"http://{IP}:{HTTP_PORT}",
        "ui": f"http://{IP}:{UI_PORT}",
        "task_queue": TASK_QUEUE,
    }


@app.get("/api/workflows")
async def list_workflows():
    import urllib.request
    body = urllib.request.urlopen(
        f"http://{IP}:{HTTP_PORT}/api/v1/namespaces/default/workflows",
        timeout=5,
    ).read().decode()
    return json.loads(body)


@app.post("/api/order/success")
async def order_success():
    order = Order(
        order_id=f"ORD-{uuid.uuid4().hex[:6]}", customer_id="CUST-42",
        items=[{"sku": "WIDGET-1", "qty": 2, "price": 29.99},
               {"sku": "GADGET-3", "qty": 1, "price": 49.99}],
        total=109.97, shipping_address="123 Main St",
    )
    result = await client.execute_workflow(
        OrderFulfillmentWorkflow.run, order,
        id=wf_id("order-ok"), task_queue=TASK_QUEUE,
    )
    return {"order_id": result.order_id, "status": result.status,
            "steps": result.steps, "tracking": result.tracking_number}


@app.post("/api/order/failure")
async def order_failure():
    order = Order(
        order_id=f"ORD-{uuid.uuid4().hex[:6]}", customer_id="CUST-99",
        items=[{"sku": "EXPENSIVE", "qty": 1, "price": 15000.00}],
        total=15000.00, shipping_address="456 Oak Ave",
    )
    result = await client.execute_workflow(
        OrderFulfillmentWorkflow.run, order,
        id=wf_id("order-fail"), task_queue=TASK_QUEUE,
    )
    return {"order_id": result.order_id, "status": result.status,
            "steps": result.steps, "tracking": result.tracking_number}


@app.post("/api/onboarding/start")
async def onboarding_start():
    user = NewUser(
        user_id=f"USR-{uuid.uuid4().hex[:6]}",
        email=f"user-{uuid.uuid4().hex[:4]}@test.com", plan="pro",
    )
    wid = wf_id("onboard")
    await client.start_workflow(
        UserOnboardingWorkflow.run, user,
        id=wid, task_queue=TASK_QUEUE,
    )
    return {"workflow_id": wid, "user": user.__dict__}


@app.post("/api/onboarding/{workflow_id}/verify")
async def onboarding_verify(workflow_id: str):
    handle = client.get_workflow_handle(workflow_id)
    await handle.signal(UserOnboardingWorkflow.verify_email)
    result = await handle.result()
    return {"status": result.status, "resources": result.provisioned_resources,
            "timeline": result.timeline}


@app.post("/api/pipeline/run")
async def pipeline_run():
    config = PipelineConfig(
        pipeline_id=f"PIPE-{uuid.uuid4().hex[:6]}",
        sources=["database", "flaky_api", "csv_export"], batch_size=100,
    )
    result = await client.execute_workflow(
        DataPipelineWorkflow.run, config,
        id=wf_id("pipeline"), task_queue=TASK_QUEUE,
    )
    return {"pipeline_id": result.pipeline_id, "records": result.records_processed,
            "sources": result.sources_completed, "valid": result.validation_passed}


@app.post("/api/expense/start")
async def expense_start():
    report = ExpenseReport(
        report_id=f"EXP-{uuid.uuid4().hex[:6]}", submitter="alice",
        amount=round(random.uniform(50, 500), 2),
        description="conference travel", category="travel",
        approval_timeout_seconds=300,  # 5 minutes for interactive use
    )
    wid = wf_id("expense")
    await client.start_workflow(
        ExpenseApprovalWorkflow.run, report,
        id=wid, task_queue=TASK_QUEUE,
    )
    return {"workflow_id": wid, "report": report.__dict__}


@app.post("/api/expense/{workflow_id}/approve")
async def expense_approve(workflow_id: str):
    handle = client.get_workflow_handle(workflow_id)
    try:
        await handle.signal(ExpenseApprovalWorkflow.approve, "manager_bob")
        result = await handle.result()
        return {"status": result.status, "approved_by": result.approved_by,
                "timeline": result.timeline}
    except Exception as e:
        return {"status": "ERROR", "error": str(e), "timeline": []}


@app.post("/api/expense/{workflow_id}/reject")
async def expense_reject(workflow_id: str):
    handle = client.get_workflow_handle(workflow_id)
    try:
        await handle.signal(ExpenseApprovalWorkflow.reject, "manager_bob")
        result = await handle.result()
        return {"status": result.status, "approved_by": result.approved_by,
                "timeline": result.timeline}
    except Exception as e:
        return {"status": "ERROR", "error": str(e), "timeline": []}


@app.post("/api/batch/run")
async def batch_run():
    items = [f"item-{i}" for i in range(25)]
    job = BatchJob(job_id=f"BATCH-{uuid.uuid4().hex[:6]}", items=items, batch_size=5)
    result = await client.execute_workflow(
        BatchProcessingWorkflow.run, job,
        id=wf_id("batch"), task_queue=TASK_QUEUE,
    )
    return {"job_id": result.job_id, "processed": result.total_processed,
            "status": result.status}


# --- Serve React static build ---

UI_DIR = Path(__file__).parent / "ui" / "dist"

if UI_DIR.exists():
    app.mount("/assets", StaticFiles(directory=UI_DIR / "assets"), name="static")

    @app.get("/{path:path}")
    async def serve_spa(path: str):
        file = UI_DIR / path
        if path and file.exists() and file.is_file():
            return FileResponse(file)
        return FileResponse(UI_DIR / "index.html")

"""
Integration test for temporal-server as an npm dependency.
Tests real-world workflow patterns: order fulfillment with saga compensation,
user onboarding with signals/timers, parallel data pipeline, approval flow
with escalation, and long-running batch processing with heartbeats.

Requires: pip install temporalio

Usage:
    python test.py
    npm test
"""

import asyncio
import json
import random
import socket
import subprocess
import sys
import time
import urllib.request
import uuid
from dataclasses import dataclass, field
from datetime import timedelta
from enum import Enum
from pathlib import Path
from typing import Optional

from temporalio import activity, workflow
from temporalio.client import Client, WorkflowFailureError
from temporalio.common import RetryPolicy
from temporalio.exceptions import ApplicationError
from temporalio.worker import Worker

ROOT = Path(__file__).parent
TEMPORAL_PKG = ROOT / "node_modules" / "temporal-server"
CFG = json.loads((TEMPORAL_PKG / "configs" / "server.json").read_text())

IP = CFG["ip"]
GRPC_PORT = CFG["port"]
HTTP_PORT = CFG["httpPort"]
UI_PORT = CFG["uiPort"]
METRICS_PORT = CFG["metricsPort"]

results = []


def pass_test(name, detail=""):
    print(f"  [PASS] {name}" + (f": {detail}" if detail else ""))
    results.append(True)


def fail_test(name, detail=""):
    print(f"  [FAIL] {name}" + (f": {detail}" if detail else ""))
    results.append(False)


def wf_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:8]}"


def port_up(port, timeout=2):
    try:
        s = socket.create_connection((IP, port), timeout=timeout)
        s.close()
        return True
    except (ConnectionRefusedError, OSError, TimeoutError):
        return False


def wait_for_port(port, timeout=30):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if port_up(port):
            return True
        time.sleep(0.5)
    return False


def http_get(url, timeout=5):
    return urllib.request.urlopen(url, timeout=timeout).read().decode()


def npm(*args):
    return subprocess.run(
        ["npm", *args], cwd=TEMPORAL_PKG,
        capture_output=True, text=True, shell=True,
    )


def start_server():
    print("Starting temporal-server...")
    npm("start")
    for port in [GRPC_PORT, HTTP_PORT, UI_PORT, METRICS_PORT]:
        if not wait_for_port(port):
            print(f"  ERROR: Port {port} did not come up within 30s")
            sys.exit(1)
    print("Server started.\n")


def stop_server():
    print("\nStopping temporal-server...")
    npm("stop")
    time.sleep(2)
    print("Server stopped.\n")


# --- Health checks ---


def test_grpc_port():
    if port_up(GRPC_PORT):
        pass_test("gRPC port", f"TCP connect to {GRPC_PORT}")
    else:
        fail_test("gRPC port", f"cannot connect to {GRPC_PORT}")


def test_http_api():
    try:
        body = http_get(f"http://{IP}:{HTTP_PORT}/api/v1/namespaces")
        data = json.loads(body)
        has_default = any(
            ns.get("namespaceInfo", {}).get("name") == "default"
            for ns in data.get("namespaces", [])
        )
        if has_default:
            pass_test("HTTP API", 'namespaces contain "default"')
        else:
            fail_test("HTTP API", "default namespace not found")
    except Exception as e:
        fail_test("HTTP API", str(e))


def test_web_ui():
    try:
        body = http_get(f"http://{IP}:{UI_PORT}")
        if "<!doctype" in body.lower() or "<html" in body.lower():
            pass_test("Web UI", "returns HTML")
        else:
            fail_test("Web UI", "not HTML")
    except Exception as e:
        fail_test("Web UI", str(e))


def test_metrics():
    try:
        body = http_get(f"http://{IP}:{METRICS_PORT}/metrics")
        if "# HELP" in body or "# TYPE" in body:
            pass_test("Metrics", "prometheus format")
        else:
            fail_test("Metrics", "no prometheus markers")
    except Exception as e:
        fail_test("Metrics", str(e))


def test_dashboard():
    try:
        body = http_get(f"http://{IP}:{UI_PORT}")
        if "<!doctype html" in body.lower() or "<html" in body.lower():
            pass_test("Dashboard HTML", "valid HTML document")
        else:
            fail_test("Dashboard HTML", "no HTML doctype")
        if "sveltekit" in body.lower() or "svelte" in body.lower():
            pass_test("Dashboard app", "SvelteKit app shell detected")
        else:
            fail_test("Dashboard app", "no SvelteKit markers")
    except Exception as e:
        fail_test("Dashboard content", str(e))


# ============================================================================
# Scenario 1: E-Commerce Order Fulfillment (Saga with compensation)
#
# Real pattern: place order -> validate inventory -> charge payment ->
# reserve shipping -> send confirmation. If any step fails, compensate
# all prior steps in reverse (refund, release inventory, cancel shipment).
# ============================================================================


@dataclass
class Order:
    order_id: str
    customer_id: str
    items: list[dict]  # [{"sku": "WIDGET-1", "qty": 2, "price": 29.99}, ...]
    total: float
    shipping_address: str


@dataclass
class OrderResult:
    order_id: str
    status: str
    steps: list[str]
    tracking_number: Optional[str] = None


@activity.defn
async def validate_inventory(order: Order) -> dict:
    # simulate inventory check across warehouses
    await asyncio.sleep(0.1)
    for item in order.items:
        if item["sku"] == "OUT-OF-STOCK":
            raise ApplicationError(
                f"Item {item['sku']} is out of stock",
                non_retryable=True,
            )
    return {
        "warehouse": "WAREHOUSE-EAST",
        "reservation_id": f"RES-{order.order_id}",
        "items_reserved": len(order.items),
    }


@activity.defn
async def charge_payment(order: Order) -> dict:
    await asyncio.sleep(0.1)
    if order.total > 10000:
        raise ApplicationError(
            f"Payment declined: amount ${order.total} exceeds limit",
            non_retryable=True,
        )
    return {
        "transaction_id": f"TXN-{uuid.uuid4().hex[:8]}",
        "amount_charged": order.total,
        "customer_id": order.customer_id,
    }


@activity.defn
async def reserve_shipping(order: Order) -> dict:
    await asyncio.sleep(0.1)
    return {
        "shipment_id": f"SHIP-{uuid.uuid4().hex[:8]}",
        "tracking_number": f"1Z{random.randint(100000, 999999)}",
        "carrier": "UPS",
        "estimated_days": 3,
    }


@activity.defn
async def send_order_confirmation(order: Order) -> str:
    await asyncio.sleep(0.05)
    return f"confirmation email sent to customer {order.customer_id}"


@activity.defn
async def release_inventory(reservation_id: str) -> str:
    await asyncio.sleep(0.05)
    return f"released reservation {reservation_id}"


@activity.defn
async def refund_payment(transaction_id: str) -> str:
    await asyncio.sleep(0.05)
    return f"refunded transaction {transaction_id}"


@activity.defn
async def cancel_shipment(shipment_id: str) -> str:
    await asyncio.sleep(0.05)
    return f"cancelled shipment {shipment_id}"


@workflow.defn
class OrderFulfillmentWorkflow:
    def __init__(self):
        self._status = "PENDING"
        self._steps: list[str] = []

    @workflow.run
    async def run(self, order: Order) -> OrderResult:
        compensations = []
        tracking = None

        try:
            # Step 1: validate and reserve inventory
            self._status = "VALIDATING_INVENTORY"
            inv = await workflow.execute_activity(
                validate_inventory, order,
                start_to_close_timeout=timedelta(seconds=10),
                retry_policy=RetryPolicy(maximum_attempts=3),
            )
            self._steps.append(f"inventory reserved: {inv['reservation_id']}")
            compensations.append(("inventory", inv["reservation_id"]))

            # Step 2: charge payment
            self._status = "CHARGING_PAYMENT"
            payment = await workflow.execute_activity(
                charge_payment, order,
                start_to_close_timeout=timedelta(seconds=10),
                retry_policy=RetryPolicy(maximum_attempts=2),
            )
            self._steps.append(f"payment charged: {payment['transaction_id']}")
            compensations.append(("payment", payment["transaction_id"]))

            # Step 3: reserve shipping
            self._status = "RESERVING_SHIPPING"
            shipping = await workflow.execute_activity(
                reserve_shipping, order,
                start_to_close_timeout=timedelta(seconds=10),
            )
            tracking = shipping["tracking_number"]
            self._steps.append(f"shipping reserved: {shipping['shipment_id']}")
            compensations.append(("shipping", shipping["shipment_id"]))

            # Step 4: send confirmation
            self._status = "CONFIRMING"
            conf = await workflow.execute_activity(
                send_order_confirmation, order,
                start_to_close_timeout=timedelta(seconds=10),
            )
            self._steps.append(conf)
            self._status = "FULFILLED"

        except Exception:
            # saga compensation: undo in reverse order
            self._status = "COMPENSATING"
            for comp_type, comp_id in reversed(compensations):
                if comp_type == "inventory":
                    r = await workflow.execute_activity(
                        release_inventory, comp_id,
                        start_to_close_timeout=timedelta(seconds=10),
                    )
                elif comp_type == "payment":
                    r = await workflow.execute_activity(
                        refund_payment, comp_id,
                        start_to_close_timeout=timedelta(seconds=10),
                    )
                elif comp_type == "shipping":
                    r = await workflow.execute_activity(
                        cancel_shipment, comp_id,
                        start_to_close_timeout=timedelta(seconds=10),
                    )
                else:
                    continue
                self._steps.append(f"COMPENSATED: {r}")
            self._status = "FAILED_COMPENSATED"

        return OrderResult(
            order_id=order.order_id,
            status=self._status,
            steps=self._steps,
            tracking_number=tracking,
        )

    @workflow.query
    def get_status(self) -> str:
        return self._status

    @workflow.query
    def get_steps(self) -> list[str]:
        return list(self._steps)


